import{_ as s,C as o,o as r,c as n,j as t,a as i,E as d,a2 as c}from"./chunks/framework.sc8Z_ZE3.js";const w=JSON.parse('{"title":"Audit, decisions and budgets","description":"","frontmatter":{},"headers":[],"relativePath":"admin/governance.md","filePath":"admin/governance.md"}'),l={name:"admin/governance.md"};function u(p,e,g,h,m,f){const a=o("Badge");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"audit-decisions-and-budgets",tabindex:"-1"},[i("Audit, decisions and budgets "),t("a",{class:"header-anchor",href:"#audit-decisions-and-budgets","aria-label":'Permalink to "Audit, decisions and budgets"'},"​")],-1)),d(a,{type:"built",text:"Built"}),e[1]||(e[1]=c(' What was done, what was refused, and what it may cost. These pages are under <strong>Operations › Govern</strong> and <strong>Admin › Models</strong>.<h2 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h2><p><strong>Operations › Audit log</strong>, for platform admins: who changed what, when and from where. Search by actor or object, filter by category and window (7, 30 or 90 days), and <strong>Export</strong> to CSV; the export is audited too.</p><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h2><p><strong>Operations › Decisions</strong>: every request a gate refused or held for approval, with its outcome, what was asked, who and where, the gate and the deciding rule. Filter by outcome, Workspace, gate and window (24 hours, 7 or 30 days). Allowed requests are counted, not listed.</p><h2 id="session-transcripts" tabindex="-1">Session transcripts <a class="header-anchor" href="#session-transcripts" aria-label="Permalink to &quot;Session transcripts&quot;">​</a></h2><p>Off by default. A Workspace admin switches on <strong>Full session transcripts</strong> under <strong>Workspace settings › Models &amp; agents › Coding tools &amp; devices</strong>, card <strong>Session transcripts</strong>. Then the full Claude Code transcript, subagents included, is uploaded after a session, redacted for secrets on the machine. Only Workspace admins and the session&#39;s owner can read it, every read is audited, and transcripts are kept for 30 days by default (1 to 3,650).</p><h2 id="budgets" tabindex="-1">Budgets <a class="header-anchor" href="#budgets" aria-label="Permalink to &quot;Budgets&quot;">​</a></h2><p><strong>Admin › Models › Budgets</strong>: a budget per Workspace or per person, per day, week or month, in USD.</p><ul><li><strong>Warn at</strong> (80 % by default): an alert, listed as an attention item under <strong>Admin › Problems</strong>.</li><li><strong>Stop at</strong> (100 % by default, up to 1,000 %): further requests are refused with the budget&#39;s name.</li><li>Budgets are switched off, never deleted.</li></ul><p>A single work item can also have a <a href="/docs/work/items#start-a-workflow">cost budget</a>: its run pauses when it reaches it.</p><h2 id="usage-costs" tabindex="-1">Usage &amp; costs <a class="header-anchor" href="#usage-costs" aria-label="Permalink to &quot;Usage &amp; costs&quot;">​</a></h2><p><strong>Operations › Usage &amp; costs</strong>: spend, priced coverage, tokens and active users, by model, by Workspace (with its budget) and the top users. Costs are the platform&#39;s estimate from list prices, not an invoice; a model without a price is counted as unpriced. Seat use is shown separately from API cost.</p><p>See also <a href="/docs/admin/operations">Operations</a>.</p>',18))])}const k=s(l,[["render",u]]);export{w as __pageData,k as default};
